CREATE TABLE `ccms_purchase_summary` (
  `CM_Purchase_Summary_ID` varchar(25) NOT NULL,
  `CM_Supplier_ID` varchar(25) DEFAULT NULL,
  `CM_Company_ID` varchar(25) DEFAULT NULL,
  `CM_Bill_Number` varchar(50) DEFAULT NULL,
  `CM_Tax_Type` enum('GST','CGST/SGST','IGST') DEFAULT 'GST',
  `CM_Tax_Percentage` decimal(15,2) DEFAULT NULL,
  `CM_Tax_Amount` decimal(15,2) DEFAULT NULL,
  `CM_Payment_Terms` varchar(100) DEFAULT NULL,
  `CM_Grand_Total` decimal(45,2) DEFAULT NULL,
  `CM_Advance_Payment` decimal(45,2) DEFAULT NULL,
  `CM_Balance_Payment` decimal(45,2) DEFAULT NULL,
  `CM_Delivery_Location` varchar(100) DEFAULT NULL,
  `CM_Delivery_Date` datetime DEFAULT NULL,
  `CM_Payment_Status` enum('Paid','Partially Paid','Unpaid') DEFAULT NULL,
  `CM_Round_off` decimal(15,2) DEFAULT NULL,
  `CM_Created_By` varchar(50) DEFAULT NULL,
  `CM_Created_At` datetime DEFAULT CURRENT_TIMESTAMP,
  `CM_Uploaded_By` varchar(50) DEFAULT NULL,
  `CM_Uploaded_At` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `CM_Total_Unit_Prices` decimal(15,2) DEFAULT '0.00',
  `CM_Total_Discount` decimal(15,2) DEFAULT '0.00',
  `CM_Final_Bill_Amount` decimal(45,2) DEFAULT '0.00',
  PRIMARY KEY (`CM_Purchase_Summary_ID`),
  UNIQUE KEY `idx_bill_company` (`CM_Bill_Number`,`CM_Company_ID`),
  KEY `fk_purchase_summary_supplier` (`CM_Supplier_ID`),
  KEY `fk_purchase_summary_company` (`CM_Company_ID`),
  CONSTRAINT `fk_purchase_summary_company` FOREIGN KEY (`CM_Company_ID`) REFERENCES `ccms_companies` (`CM_Company_ID`),
  CONSTRAINT `fk_purchase_summary_supplier` FOREIGN KEY (`CM_Supplier_ID`) REFERENCES `ccms_suppliers` (`CM_Supplier_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
